"""Build the complete original p.5 story and eight adapted comprehension questions."""
import copy,json,sys
from pathlib import Path
from html import escape
from lxml import html
from preintermediate1_unit4_christmas_reading_content import TITLE,ORIGINAL_TITLE,PARAGRAPHS,QUESTIONS,INSTRUCTION,VOCABULARY,AUDIO
ROOT=Path(__file__).resolve().parents[1];COURSE=ROOT/'ingles/preintermedio-1'
NAME='reading-unit-4-getting-ready-for-christmas.html';PDF='materials/christmas-around-the-world-original.pdf'
PREVIOUS='vocabulary-unit-4-celebration-expressions.html';CONNECTED='reading-unit-4-saturdays-celebration-plan.html'
MEDIA='/assets/img/english-preintermediate-1/unit-4/practice/christmas-reading/';VERSION='20261123-christmas-reading-1'
def fragment(text):return html.fragment_fromstring(text)
def write(name,doc):(COURSE/name).write_text('<!doctype html>\n'+html.tostring(doc,encoding='unicode',method='html')+'\n')
def listen(key,label):return f'<button type="button" class="btn btn-secondary" data-cr-audio="{key}">{escape(label)}</button>'
def folder(id,num,title,text):return f'<details class="pi-topic" id="{id}"><summary><span class="pi-number">{num}</span><h2>{title}</h2></summary><div class="pi-topic-body">{text}</div></details>'
doc=html.document_fromstring((COURSE/'course-overview.html').read_text());description='Read and listen to the complete Smith family Christmas story, then answer eight questions using evidence from the text.'
doc.find('.//title').text=TITLE+' · Reading | Preintermediate English Course 1';doc.xpath('//meta[@name="description"]')[0].set('content',description)
doc.xpath('//link[contains(@href,"course-responsive.css")]')[0].addprevious(fragment(f'<link rel="stylesheet" href="/assets/css/preintermediate1-christmas-reading.css?v={VERSION}">'))
body=doc.find('.//body');body.set('class','english-basic-page basic2-page preinter-page pi-practice-page pi-connected-page cr-page')
for script in body.xpath('./script[contains(@src,"preintermediate1-")]'):body.remove(script)
for a in doc.xpath('//header//a[@aria-current]'):a.attrib.pop('aria-current',None)
doc.xpath('//header//ul[contains(@class,"nav-links")]')[0].append(fragment('<li><a href="practice-lab.html">Practice Lab</a></li>'))
main=doc.find('.//main');hero=copy.deepcopy(main[0]);main.clear();main.set('id','main-content');main.set('data-jaralingua-managed-draft','true')
hero.set('style',f'--hero-image:url({MEDIA}cover.webp)');hero.xpath('.//p[@class="eyebrow"]')[0].text='Practice Lab · Unit 4 · Reading';hero.xpath('.//h1')[0].text=TITLE
hero.xpath('.//div[contains(@class,"pi-hero-copy")]/p[not(@class="eyebrow")]')[0].text=description
actions=hero.xpath('.//div[contains(@class,"hero-actions")]')[0];actions.clear();actions.set('class','hero-actions pi-actions')
actions.extend(html.fragments_fromstring(f'<a class="btn btn-primary" href="#reading-story">Start reading</a><a class="btn btn-secondary" href="{PDF}" download="Christmas Around the World - ESL Pals.pdf">Download original PDF</a><a class="btn btn-secondary" href="practice-lab.html#unit-4-reading">Unit 4 reading activities</a>'))
im=hero.xpath('.//figure/img')[0];im.set('src',MEDIA+'cover.webp');im.set('alt','A fictional family decorating a Christmas tree while the mother writes a greeting card');im.set('width','1600');im.set('height','800');main.append(hero)
content='''<section class="pi-objective cr-intro"><p class="pi-label">Christmas Around the World · ESL Pals · Page 5 · Reading</p><h2>Your reading goal</h2><p>Follow what the Smith family are doing, find details about their home and customs, and notice the order of the tree decorations.</p><div class="pi-route"><span>Complete original story · 7 paragraphs</span><span>8 text-based questions</span><span>Full and paragraph audio</span></div><p class="pi-small">Read the story or listen while following the text. Hover or focus on an underlined word for its Spanish meaning; tap it to hear the pronunciation. The eight questions are adapted for reading comprehension. Personal comparisons belong to Speaking.</p><p class="pi-small">Complete all eight questions before checking. Explanations and evidence appear after two different complete attempts, or a perfect first attempt. Repeating the same choices does not add an attempt. Your choices stay in this browser tab and Start again has an undo option. This is practice only; no official grade or teacher submission is created.</p><p id="cr-storage-status" class="pi-small" role="status" hidden></p></section>'''
content+='''<section class="pi-objective cr-player" aria-label="Story, question and vocabulary audio"><h2>Listen and read</h2><div class="pi-actions"><button type="button" class="btn btn-primary" data-cr-audio="story">Listen to the complete story</button><button type="button" class="btn btn-secondary" id="cr-pause-resume" disabled>Pause audio</button><button type="button" class="btn btn-secondary" id="cr-stop" disabled>Stop audio</button><button type="button" class="btn btn-secondary" id="cr-retry" hidden>Retry selected audio</button></div><div class="pi-audio-controls"><span>Audio speed</span><button type="button" data-cr-speed="0.75" aria-pressed="false">0.75×</button><button type="button" data-cr-speed="1" aria-pressed="true">1.0×</button><button type="button" data-cr-speed="1.25" aria-pressed="false">1.25×</button><span id="cr-audio-status" role="status" aria-live="polite">Choose the complete story, a paragraph, a question or an underlined word.</span></div><audio id="cr-audio" controls preload="none" aria-label="Selected reading or vocabulary audio"></audio></section>'''
story=f'<article class="cr-article"><h2 class="cr-original-title">{ORIGINAL_TITLE}</h2><div class="cr-paragraphs">'
for n,paragraph in enumerate(PARAGRAPHS,1):story+=f'<section class="cr-paragraph" id="reading-paragraph-{n}"><div class="cr-paragraph-tools"><span>Paragraph {n}</span>'+listen('paragraph-'+str(n),'Listen to paragraph '+str(n))+f'</div><p class="cr-original-paragraph" data-glossary>{escape(paragraph)}</p></section>'
story+='</div><p class="pi-small">Complete story: ESL Pals · Christmas Around the World · Page 5. The Smith family and their customs belong to this fictional story.</p></article>'
content+=folder('reading-story','Read','Read and listen · Complete story',story)
quiz='<div class="cr-instruction"><p>'+escape(INSTRUCTION)+'</p>'+listen('instruction','Listen to the reading instruction')+'</div><p class="pi-small">Each question has one answer supported by the story. Use the text, rather than your own family customs.</p><p id="cr-count" class="cr-count" role="status" aria-live="polite">0 of 8 answered.</p><form id="cr-quiz"><div class="cr-questions-grid">'
for q in QUESTIONS:
    uid=q['id'];n=q['number'];quiz+=f'<fieldset class="cr-question" data-cr-question="{uid}" id="reading-question-{n}"><legend>{n}. <span data-glossary>{escape(q["question"])}</span></legend>'+listen('question-'+str(n),'Listen to question '+str(n))
    for letter,option in q['options'].items():quiz+=f'<label class="cr-choice" for="cr-{uid}-{letter}"><input type="radio" id="cr-{uid}-{letter}" name="{uid}" value="{letter}"><span><b>{letter}.</b> {escape(option)}</span></label>'
    quiz+='<div class="cr-feedback" hidden><p class="cr-answer"></p><p class="cr-explanation"></p><blockquote></blockquote><a href="#reading-paragraph-'+str(q['paragraph'])+'">Read the evidence in paragraph '+str(q['paragraph'])+'</a></div></fieldset>'
quiz+='</div><div class="pi-actions"><button type="submit" class="btn btn-primary" id="cr-check">Check answers</button><button type="button" class="btn btn-secondary" id="cr-reset">Start again</button><button type="button" class="btn btn-secondary" id="cr-undo" hidden>Undo reset</button><a class="btn btn-secondary" href="#reading-story">Back to the story</a></div><p id="cr-result" class="cr-result" role="status" aria-live="polite" tabindex="-1" hidden></p></form>'
content+=folder('comprehension-check','Check','Reading comprehension · 8 questions',quiz)
content+=folder('vocabulary-support','Aa','Vocabulary support','<p>Review the words and phrases used in the story.</p><ul class="cr-wordbox">'+''.join('<li><span data-glossary>'+escape(v['term'])+'</span></li>' for v in VOCABULARY)+'</ul>')
original=f'<figure class="cr-original-page"><img src="{MEDIA}original-page-5.webp" width="1275" height="1802" alt="Complete original ESL Pals page 5 with the Christmas story and classroom discussion questions" loading="lazy"><figcaption>ESL Pals · Christmas Around the World · Original page 5. The story is complete and unchanged.</figcaption></figure><div class="cr-source-note"><h3>Reading adaptation notes</h3><p>The original question about Grandpa asks why he sleeps after lunch, but the story only states when he usually sleeps. Question 3 asks when. The original personal comparison question is reserved for Speaking; Question 8 here checks the order of the tree decorations. The other questions are adapted as multiple-choice reading questions.</p><p>The source uses British collective agreement in the Smith family are and the Smith family always go. That wording is preserved.</p></div>'
content+=folder('original-page','PDF','View the original worksheet · Page 5',original)
content+=f'<section class="pi-objective cr-footer"><div><h2>Original PDF · 9 pages</h2><p>Original story: ESL Pals, <cite>Christmas Around the World</cite>, page 5. The complete PDF is provided unchanged. The eight multiple-choice questions on this page are an adapted course activity based only on the story.</p></div><div class="pi-actions"><a class="btn btn-primary" href="{PDF}" download="Christmas Around the World - ESL Pals.pdf">Download original PDF</a><a class="btn btn-secondary" href="{PREVIOUS}">Previous · Celebration Expressions Vocabulary</a><a class="btn btn-secondary" href="practice-lab.html#unit-4-reading">Unit 4 reading activities</a></div></section><noscript><p class="pi-objective">Read the complete story or download the PDF to work on paper. Enable JavaScript for audio, meanings, checking and draft recovery.</p></noscript>'
main.append(fragment('<div class="pi-shell">'+content+'</div>'))
data=html.Element('script',id='cr-data',type='application/json');data.text=json.dumps(dict(title=TITLE,paragraphs=PARAGRAPHS,questions=QUESTIONS,vocabulary=VOCABULARY,audio=AUDIO),ensure_ascii=False).replace('<','\\u003c');body.append(data)
for src in ['/assets/js/first-visit-vocabulary.js?v=20261031-personality-speaking','/assets/js/preintermediate1-christmas-reading.js?v='+VERSION]:body.append(fragment('<script src="'+src+'"></script>'))
write(NAME,doc)
card=f'<article class="course-section-card"><div class="course-section-image"><img src="{MEDIA}cover.webp" alt="A fictional family preparing a Christmas tree at home" width="1600" height="800" loading="lazy" decoding="async"></div><div class="course-section-content"><span class="section-number">02</span><span class="course-status course-status-available">Reading · Available now</span><h3>{TITLE}</h3><p>Complete original story, full and paragraph audio, and 8 comprehension questions.</p><a class="card-link" href="{NAME}">Open Christmas story reading</a></div></article>'
lab=html.document_fromstring((COURSE/'practice-lab.html').read_text());unit=lab.get_element_by_id('unit-4');unit_body=unit.xpath('./div[contains(@class,"pi-topic-body")]')[0]
old=unit.xpath('.//article[.//a[@href=$v]]',v=CONNECTED);assert len(old)==1
connected=old[0];connected.getparent().remove(connected);connected.xpath('.//span[@class="section-number"]')[0].text='01'
for previous in unit_body.xpath('./details[@id="unit-4-reading"]'):unit_body.remove(previous)
reading_group=fragment('<details class="pi-topic" id="unit-4-reading"><summary><span class="pi-number">Read</span><h3>Reading · Celebrations and Festivals</h3></summary><div class="pi-topic-body"><p>Read the connected celebration plan or the complete original Christmas story. Both pages include vocabulary support.</p><div class="pi-section-grid"></div></div></details>')
grid=reading_group.xpath('.//div[@class="pi-section-grid"]')[0];grid.append(connected);grid.append(fragment(card));unit_body.append(reading_group)
unit_body.xpath('./p[contains(@class,"pi-goal")]')[0].text='Sessions 9–10 · 6 hours of class · 6 activities available'
intro=lab.xpath('//section[@class="pi-objective"]/p')[0]
intro.text=(intro.text or '').replace('Unit 4 adds Celebration Words and Objects, Celebration Expressions vocabulary, and Customs and Celebration Descriptions grammar.','Unit 4 adds Celebration Words and Objects, Celebration Expressions vocabulary, Customs and Celebration Descriptions grammar, and Getting Ready for Christmas reading.')
write('practice-lab.html',lab)
library=html.document_fromstring((COURSE/'listening-library.html').read_text());shell=library.get_element_by_id('unit-audio-library')
for old in shell.xpath('./section[@id="unit-4-christmas-reading-audio"]'):shell.remove(old)
shell.get_element_by_id('unit-4').addprevious(fragment('<section class="pi-objective" id="unit-4-christmas-reading-audio"><h2>Unit 4 · Getting Ready for Christmas reading audio</h2><p>Listen to the complete original story, replay one of its seven paragraphs, or hear a comprehension question and vocabulary.</p><div class="pi-library-activities">'+card+'</div></section>'));write('listening-library.html',library)
previous=html.document_fromstring((COURSE/PREVIOUS).read_text());footer=previous.xpath('//section[contains(@class,"ce-footer")]')[0]
for old in footer.xpath('.//a[@href=$v]',v=NAME):old.getparent().remove(old)
footer.xpath('.//a[contains(@href,"practice-lab")]')[0].addprevious(fragment(f'<a class="btn btn-secondary" href="{NAME}">Next · Getting Ready for Christmas Reading</a>'));write(PREVIOUS,previous)
try:import qrcode
except ModuleNotFoundError:sys.path.insert(0,str(ROOT/'tmp/unit5-explanation/python-deps'));import qrcode
import qrcode.image.svg
qrcode.make('https://www.jaralingua.com/ingles/preintermedio-1/'+NAME,image_factory=qrcode.image.svg.SvgPathImage,box_size=10,border=4).save(ROOT/'assets/img/page-qr'/('ingles-preintermedio-1-'+NAME.removesuffix('.html')+'.svg'))
print('Built complete Christmas story, eight adapted comprehension questions and separate Reading folder.')
